tools.handlerExpression:
async (args) => {
          try {
            const operations = await loadOperations(request);
            const query2 = args.query ?? "";
            const limit = args.limit ?? 5;
            const includeSchema = args.include_schema !== false;
            const selected = operations.map((operation) => ({
              operation,
              score: scoreOperation(query2, operation),
            })).filter((item) => item.score > 0).sort((a, b) => {
              const preferredRank = (operationId) => {
                const index = PREFERRED_OPERATIONS.indexOf(operationId);
                return index >= 0 ? index : Number.MAX_SAFE_INTEGER;
              };
              return b.score - a.score ||
                preferredRank(a.operation.id) - preferredRank(b.operation.id) ||
                (a.operation.id < b.operation.id ? -1 : 1);
            }).slice(0, limit).map((item) => operationSummary(item.operation, includeSchema));
            return textResult({
              ok: true,
              provider: "cloudflare",
              operation_count: operations.length,
              operations: selected,
            });
          } catch (err) {
            return textResult({
              ok: false,
              provider: "cloudflare",
              error: err instanceof Error ? err.message : String(err),
            });
          }
        }

