tools.schemaExpression:
{
          operation_id: exports_external.string().describe(
            "Exact Cloudflare operation id, e.g. cloudflare.accounts.list, cloudflare.zones.list, cloudflare.dns.records.list.",
          ),
          input: exports_external.record(exports_external.string(), exports_external.unknown())
            .optional().describe(
              "Operation input object. Use mcp__cloudflare__search first to inspect required parameters.",
            ),
          dry_run: exports_external.boolean().optional().describe(
            "For read operations only, asks the gateway to dry-run when supported.",
          ),
          connection_id: exports_external.string().optional().describe(
            "Only pass when multiple Cloudflare connections are explicitly selected.",
          ),
          idempotency_key: exports_external.string().optional().describe(
            "Optional stable key for write planning/execution retries.",
          ),
        }

tools.handlerExpression:
async (args) => {
          try {
            const operationId = args.operation_id.trim();
            const operations = await loadOperations(request);
            const operation = operations.find((candidate) => candidate.id === operationId);
            if (!operation) {
              return textResult({
                ok: false,
                provider: "cloudflare",
                operation_id: operationId,
                error: "Unknown Cloudflare operation. Use mcp__cloudflare__search first.",
              });
            }
            const connection = await resolveConnection(
              request,
              deps.workspaceId,
              args.connection_id?.trim() || undefined,
            );
            if ("error" in connection) {
              return textResult({
                ok: false,
                provider: "cloudflare",
                operation_id: operationId,
                error: connection.error,
                connection_count: connection.connection_count,
              });
            }
            const workspaceId = deps.workspaceId ?? connection.workspace_id;
            const body = {
              connection_id: connection.id,
              provider: "cloudflare",
              operation_id: operationId,
              input: args.input ?? {},
              ...workspaceId ? { workspace_id: workspaceId } : {},
            };
            if (args.dry_run) body.dry_run = true;
            if (args.idempotency_key?.trim()) body.idempotency_key = args.idempotency_key.trim();
            const risk = operation.risk ?? "unknown";
            const path = risk === "read"
              ? "/v1/integrations/operations/execute"
              : "/v1/integrations/operations/plan";
            const payload = await request("POST", path, { body, workspaceId });
            return textResult({
              ok: true,
              provider: "cloudflare",
              operation_id: operationId,
              risk,
              status: risk === "read" ? "executed" : "confirmation_required",
              executor: risk === "read" ? "matrix_native" : "matrix_native_plan",
              data: sanitizeExecutionData(operationId, payload),
            });
          } catch (err) {
            return textResult({
              ok: false,
              provider: "cloudflare",
              operation_id: args.operation_id,
              error: err instanceof Error ? err.message : String(err),
            });
          }
        }

